package ro.leo.visual;
import ro.leo.i18n.L;import android.content.*;import android.os.*;import android.widget.*;import java.util.*;
public final class CompanionActivity extends LeoActivity {
 final Handler timer=new Handler();protected void onResume(){super.onResume();show();}protected void onPause(){timer.removeCallbacksAndMessages(null);super.onPause();}
 void show(){final CompanionService live=CompanionService.instance;if(live==null)list(L.t("Companion PC"),Arrays.asList(L.t("Pornește sesiune Wi-Fi · 15 minute"),L.t("Fișiere primite"),L.t("Pachete Leo și revenire"),getSharedPreferences("companion",0).getString("error",L.t("Transfer local cu autentificare. HTTP în rețeaua Wi-Fi; folosește o rețea de încredere."))),0,new Choice(){public void pick(final int n){if(n==0){getSharedPreferences("companion",0).edit().remove("error").apply();startForegroundService(new Intent(CompanionActivity.this,CompanionService.class));timer.postDelayed(new Runnable(){public void run(){show();}},1200);}else if(n==1)files();else if(n==2)startActivity(new Intent(CompanionActivity.this,UpdatesActivity.class));}},"",null);else{begin(L.t("Companion PC · Activ"));ScrollView scroll=new ScrollView(CompanionActivity.this);scroll.addView(text(live.address+"\n\nToken\n"+live.secret+"\n\n"+L.t("Introdu tokenul în browser. Numai folderul Companion este partajat. Sesiunea se închide după 15 minute."),16));root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));scroll.setFocusableInTouchMode(true);scroll.requestFocus();left=new Runnable(){public void run(){stopService(new Intent(CompanionActivity.this,CompanionService.class));timer.postDelayed(new Runnable(){public void run(){show();}},250);}};footer(L.t("Oprește"),L.t("Derulează"),L.t("Înapoi"));}}
 void files(){startActivity(new Intent(CompanionActivity.this,FilesActivity.class).putExtra("folder",CompanionServer.folder(CompanionActivity.this).getPath()));}
}
